/**
 * FSM Orders Preview Table for InvestAI Enterprise Rebalancing.
 * Renders proposed BUY/SELL orders generated by the Tolerance Band Rebalancer FSM,
 * execution estimates, and quantitative justifications.
 */

import React from "react";
import {
  ArrowDownLeft,
  ArrowUpRight,
  Clock,
  FileText,
  ShieldCheck,
} from "lucide-react";
import { formatMoney, formatNumber } from "@/lib/formatters";
import { RebalanceOrder } from "@/types/api";

interface FSMOrdersPreviewTableProps {
  orders: RebalanceOrder[];
  baseCurrency?: "ARS" | "USD";
}

export const FSMOrdersPreviewTable: React.FC<FSMOrdersPreviewTableProps> = ({
  orders,
  baseCurrency = "ARS",
}) => {
  if (orders.length === 0) {
    return (
      <div className="rounded-xl bg-slate-900 border border-slate-800 p-8 text-center space-y-3">
        <div className="h-10 w-10 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center mx-auto text-emerald-400">
          <ShieldCheck className="h-5 w-5" />
        </div>
        <h4 className="text-sm font-semibold text-slate-100">
          Cartera en Equilibrio Cuantitativo
        </h4>
        <p className="text-xs text-slate-400 max-w-md mx-auto">
          Ningún activo ha perforado sus bandas de tolerancia estipuladas. No se requieren órdenes de rebalanceo en este momento.
        </p>
      </div>
    );
  }

  return (
    <div className="rounded-xl bg-slate-900 border border-slate-800 shadow-xl overflow-hidden">
      {/* Title Bar */}
      <div className="px-6 py-4 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <FileText className="h-4 w-4 text-sky-400" />
          <h3 className="font-semibold text-sm text-slate-100">
            Propuesta de Órdenes FSM ({orders.length}{" "}
            {orders.length === 1 ? "orden" : "órdenes"})
          </h3>
        </div>
        <span className="text-[11px] font-mono text-slate-400">
          Estado FSM: Pendiente de Ejecución
        </span>
      </div>

      {/* Responsive Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left text-xs border-collapse">
          <thead>
            <tr className="border-b border-slate-800 bg-slate-950/60 text-[11px] font-mono uppercase text-slate-400 tracking-wider">
              <th className="py-3 px-4">Ticker</th>
              <th className="py-3 px-3 text-center">Operación</th>
              <th className="py-3 px-4 text-right">Monto Delta</th>
              <th className="py-3 px-4 text-right">Acciones Est.</th>
              <th className="py-3 px-4 text-right">Precio Ref.</th>
              <th className="py-3 px-3 text-center">Estado</th>
              <th className="py-3 px-4">Justificación Cuantitativa</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/60 font-mono">
            {orders.map((o, idx) => {
              const isBuy = o.side === "BUY";
              const isSell = o.side === "SELL";

              return (
                <tr
                  key={`${o.ticker}-${idx}`}
                  className="hover:bg-slate-800/40 transition-colors"
                >
                  {/* Ticker */}
                  <td className="py-3.5 px-4 font-bold text-white text-sm">
                    {o.ticker}
                  </td>

                  {/* Operation Side */}
                  <td className="py-3.5 px-3 text-center">
                    <span
                      className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                        isBuy
                          ? "bg-emerald-500/15 text-emerald-300 border border-emerald-500/30"
                          : isSell
                          ? "bg-rose-500/15 text-rose-300 border border-rose-500/30"
                          : "bg-slate-800 text-slate-400 border border-slate-700"
                      }`}
                    >
                      {isBuy && <ArrowUpRight className="h-3 w-3" />}
                      {isSell && <ArrowDownLeft className="h-3 w-3" />}
                      {o.side}
                    </span>
                  </td>

                  {/* Delta Amount */}
                  <td className="py-3.5 px-4 text-right font-semibold text-slate-100 tabular-nums">
                    {formatMoney(o.delta_amount, baseCurrency)}
                  </td>

                  {/* Estimated Shares */}
                  <td className="py-3.5 px-4 text-right text-slate-200 tabular-nums">
                    {formatNumber(o.estimated_shares, 0)}
                  </td>

                  {/* Reference Price */}
                  <td className="py-3.5 px-4 text-right text-slate-400 tabular-nums">
                    {formatMoney(o.price_used, baseCurrency)}
                  </td>

                  {/* Status Badge */}
                  <td className="py-3.5 px-3 text-center">
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-mono bg-sky-500/10 text-sky-400 border border-sky-500/20">
                      <Clock className="h-3 w-3" />
                      {o.status || "PENDING"}
                    </span>
                  </td>

                  {/* Justification */}
                  <td className="py-3.5 px-4 text-slate-400 font-sans text-xs max-w-xs">
                    {o.justification || "Rebalanceo por perforación de banda de tolerancia."}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};
